    bgr_steps_h: "5 ಹಂತಗಳಲ್ಲಿ ಬ್ಯಾಕ್‌ಗ್ರೌಂಡ್ ತೆಗೆಯಿರಿ",
    bgr_s1_t: "ಫೋಟೋ ಆಯ್ಕೆಮಾಡಿ",
